  insert into public.brands (name, website, description, country, status) values ('PSA Skincare', 'https://psaskincare.shop', 'PSA (Purposeful Skincare by Allies) is the affordable sister line of Allies of Skin, launched in March 2020 by founder Nicolas Travis and aimed at Gen Z and millennial shoppers, selling numbered-routine cleansers, toners, serums, night oils and creams built around actives such as mandelic acid, vitamin C and bakuchiol, through its own store and retailers including Sephora Asia, Beauty Bay and ASOS.', 'Singapore', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'hello@psaskincare.group', null, 'https://psaskincare.shop/pages/affiliates', 'verified', now());
