  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PSA Skincare Affiliate Program (Shopify Collabs / LTK / Impact)', 'https://psaskincare.shop/pages/affiliates', 'https://psaskincare.shop/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://psaskincare.shop/pages/affiliates', 'official_site', 'affiliate', 'PSA''s official affiliates page states the standard offer is 15% commission (higher for larger affiliates), up to 25% via Shopify Collabs and 10-20% via Impact, and states verbatim: ''We don''t believe in limiting potential... All commissions are uncapped.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://psaskincare.shop/pages/affiliates', 'official_site', 'contact', 'The same official page publishes hello@psaskincare.group as the contact for affiliate questions and routes sign-ups through Shopify Collabs, LTK (for individual influencers) or Impact (for publishers), with a 30-day cookie window.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.womensweekly.com.sg/beauty-and-health/5-singapore-beauty-brands-expanding-globally-during-pandemic?ref=related', 'listing', 'general', 'Women''s Weekly (Singapore) describes PSA as an offshoot of home-grown cult brand Allies of Skin, launched March 2020 as a Gen-Z and millennial-focused line with pocket-friendly prices, distributed via Sephora Malaysia/Thailand/Hong Kong, Beauty Bay and Beautylish.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://simplelifereviews.com/en/reviews/psa-skincare-review-2026-prices-evidence-returns', 'listing', 'ugc_collab', 'Simple Life Reviews'' roundup notes independent first-hand coverage of PSA is thin — a Women''s Health UK whole-range write-up from November 2020 and one InStyle partnerships piece from December 2025 — indicating a small creator/review footprint relative to its parent brand.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 16, 13, 9, 5, '{"compensation": "Published rates on the brand''s own page \u2014 15% standard, up to 25% on Shopify Collabs, 10-20% on Impact \u2014 with commissions explicitly stated as uncapped.", "contact_access": "A published affiliate contact email (hello@psaskincare.group) on the official program page plus three platform sign-up routes \u2014 top band per the rubric.", "credibility": "Sister brand of Allies of Skin with Sephora Asia and major e-tailer distribution since its March 2020 launch.", "niche_fit": "Actives-led skincare aimed at Gen Z/millennial routine builders \u2014 squarely in the skincare UGC niche.", "opportunity_availability": "Open sign-up today through Shopify Collabs, LTK or Impact, with the brand inviting affiliates to reach out directly.", "ugc_evidence": "A structured multi-platform affiliate program actively recruiting influencers and publishers, though independent creator coverage of the brand is still thin."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Face Pilates', 'https://face-pilates.com', 'Toronto skincare brand founded by Thomas Tullo, founder of AMAN Spa in Toronto, selling biocellulose and hydrogel sheet masks (the Reformer Face Mask and Under-Eye Mask, formulated with NAD+, NMN and creatine) and facial tools, positioned around natural facial sculpting.', 'Canada', 'published') returning id into bid;
