  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Face Pilates Partner Program', 'https://face-pilates.com/en-us/pages/affiliate-program', 'https://face-pilates.com/en-us/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://face-pilates.com/en-us/pages/affiliate-program', 'official_site', 'affiliate', 'Face Pilates'' official Partner Program page states partners earn 5% to 15% per product sale by tier and states verbatim: ''No caps, no minimum order thresholds — every product order your content drives counts.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://face-pilates.com/en-us/pages/affiliate-program', 'official_site', 'ugc_collab', 'The page says the program is ''Now accepting Fire Starter creators and spa professionals'', pitches the brand as one ''your followers have not seen a hundred times already'', sets a low 3,000-follower minimum for creators, and gives every partner a welcome kit with monthly content deliverables by tier.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://face-pilates.com/en-us/pages/affiliate-program', 'official_site', 'general', 'The page''s brand details describe Face Pilates as a Toronto skincare brand founded by Thomas Tullo (founder of AMAN Spa in Toronto) making biocellulose and hydrogel sheet masks and facial tools, with coverage in ELLE Canada, FASHION, Toronto Star and CTV.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 12, 10, 8, 3, '{"compensation": "Published tiered rates of 5-15% per sale on the brand''s own page with commissions explicitly uncapped, though entry tier starts at 5%.", "contact_access": "A full application form on the official page with personal review and a reply promised within five business days, but no published email.", "credibility": "New Toronto brand with national press/TV coverage listed on its own page and two independent consumer studies behind its masks, but a short track record.", "niche_fit": "Skincare masks and facial-sculpting tools built for routine content \u2014 strong fit for skincare and beauty creators.", "opportunity_availability": "Applications are open now for the entry Fire Starter tier, with a low 3,000-follower minimum for creators and no minimum for spa professionals.", "ugc_evidence": "A structured creator program with defined monthly deliverables, welcome kits and quarterly tier reviews, currently recruiting its first creator tiers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Only1', 'https://only1.co', 'Online-only luxury cosmetics brand selling clean, vegan makeup (its ColorEccentric line) made with European and American craftsmanship, sold exclusively through its own platform and promoted through a small, selective network of Envoy partners rather than retail stores.', 'United States', 'published') returning id into bid;
