  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 18, 8, 5, 3, '{"compensation": "25% commission for the lifetime of the partnership with weekly payouts and an explicit ''no cap on your potential'' statement \u2014 among the strongest published offers in this batch.", "contact_access": "A live application listing, but no published email or open program page on the brand''s own site \u2014 mid-range per the rubric.", "credibility": "New online-only luxury brand built by beauty-industry insiders, but with little independent track record so far.", "niche_fit": "Luxury vegan makeup built entirely around influencer and ambassador selling \u2014 a core beauty UGC niche.", "opportunity_availability": "Applications are open, but the program is highly selective (first 25 Envoys) and asks for prior sales or retail beauty experience.", "ugc_evidence": "A dedicated Envoy program for beauty influencers with mentorship, marketing support and a toolkit, currently recruiting its first cohort."}'::jsonb);
