  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pro.goldielocks.com/pages/beauty-affiliate-program', 'official_site', 'affiliate', 'Goldie Locks'' official Pro Affiliate Program page publishes tiered commissions — 10% (Insider), 15% (Muse), 20% (Star), 25% (Icon) by total sales — and lists ''Unlimited earning potential'' among the program details.', 'verified', now());
