  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nasdaq.com/press-release/only-of-its-kind-filterbaby-launches-on-thirteen-lune-2023-10-03', 'listing', 'general', 'The brand''s Thirteen Lune launch release reports that since its 2022 inception Filterbaby had sold nearly 100,000 units and built over half a million social followers and one billion views across Instagram, TikTok and YouTube — evidence of a large existing audience, so low creator saturation could NOT be evidenced for this brand and saturation is marked unknown.', 'publicly_reported', now());
