  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.beginningboutique.com/pages/affiliate-program?srsltid=AfmBOoreN27sIsgVh4c9qaBuq8eonDVB4_ZNWhrvQq4XGM9o6-pAzdf4', 'official_site', 'affiliate', 'Official Affiliate Program page fetched via browser.open: sign up, receive a dashboard, unique code and link, track commission; perks include commission, gifted products, feature opportunities and a BB Ambassador community. Sign-up buttons link to Impact (app.impact.com). Requirements: US/AU/NZ, public social account, 16+.', 'verified', now());
