  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/beginning-boutique', 'listing', 'ugc_collab', 'CREATOR_SATURATION = LOW: Beacons Universe reports only 4 sponsored posts mentioned Beginning Boutique in the last 12 months, 247 public mention posts in 12 months, and only 18 creators mentioned it in the 30 days to 2026-11-20 — very few sponsored creators relative to brand size.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 15, 9, 14, 9, 5, '{"compensation": "5% per sale published in affiliate listings, and the official FAQ states there is no earnings limit (''There isn''t one!''), supporting uncapped commission.", "contact_access": "Public affiliate/ambassador application page on the brand''s own site, signing up via Impact.", "credibility": "Established Australian brand founded in 2008, verified on its official About and Affiliate pages.", "niche_fit": "Core young women''s occasion and festival fashion, a direct fit for fashion UGC.", "opportunity_availability": "Publicly open application for US/AU/NZ creators aged 16+ with a public social account.", "ugc_evidence": "Named BB Ambassador program with gifting, features and events, but only 4 sponsored posts in the last 12 months on Beacons, indicating a small active sponsored roster."}'::jsonb);
