  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Edikted Ambassador / Influencer Platform (including College Ambassador)', 'https://collabs.edikted.com/', 'https://collabs.edikted.com/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://edikted.com/pages/our-story', 'official_site', 'general', 'Official Our Story page: ''Edikted, created by the founding members of a previous successful clothing brand, is a Gen-Z-orientated online fashion brand... Headquartered in Los Angeles, California.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabs.edikted.com/', 'official_site', 'ugc_collab', 'Official influencer platform fetched via browser.open: ''Hey Bestie, Looking To Collab With Us? Apply to become an ambassador by filling in your email address'' — accounts must be public. Separate listings confirm open College Ambassador and Sorority Collaborations for 18+, full-time US college students.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/edikted/', 'affiliate_network', 'compensation', 'UpPromote affiliate directory reports Edikted at 5%-10% commission depending on platform and partner tier, primarily on Impact Radius and ShareASale, 30-day cookie. However, Glossy reported Edikted stating ''We don''t have an affiliate program at all'' and using gifting with optional discount codes, and a 2026 creator-code test lists Edikted creator earnings as ''Not published'', so terms are conflicting. COMMISSION_CAP: No cap or ''no cap/unlimited'' wording was found in any fetched source, so commission_cap is ''unknown''.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://archive.com/blog/edikted-influencer-marketing-strategy', 'creator_report', 'ugc_collab', 'CREATOR_SATURATION = HIGH: Archive.com breakdown states Edikted built ''a creator network that generates thousands of sponsored posts annually'' and ''They work with thousands of unique influencers, with the majority being smaller creators'' — a volume-over-vanity, always-on micro-influencer engine, the opposite of low saturation.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usesnippet.app/blog/ambassador-programs-for-small-influencers', 'listing', 'ugc_collab', 'Snippet''s November 2026 review of creator program pages lists Edikted College Ambassador and Sorority Collaborations as ''Open'' for 18+, full-time US college students with public socials.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 20, 7, 14, 9, 5, '{"compensation": "Affiliate directory reports 5-10%, but the brand''s own model is described as gifting with optional codes and published creator earnings could not be confirmed, and no cap terms were found.", "contact_access": "Public ambassador application on the brand''s own collabs platform, plus an open College Ambassador route.", "credibility": "Established, fast-growing Gen Z brand headquartered in Los Angeles with multiple US stores, verified on its official site.", "niche_fit": "Pure Gen Z trend fashion built for TikTok/Instagram UGC \u2014 hauls, GRWM and campus content.", "opportunity_availability": "Ambassador and College Ambassador applications are publicly open now, requiring only public social accounts / student status.", "ugc_evidence": "Thousands of unique influencers and thousands of sponsored posts annually documented by Archive.com, plus open ambassador and sorority programs."}'::jsonb);
