  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopcsb.com/pages/affiliate-terms-conditions', 'official_site', 'affiliate', 'Official Affiliate Influencer Program terms: commission is ''based on tracked and qualifying sales generated through your unique affiliate link, as outlined in your Program dashboard or agreement'' and paid monthly. No percentage rate and no cap / no ''unlimited earnings'' wording is stated in the terms.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yazing.com/cashback/shopcsb', 'affiliate_network', 'compensation', 'Third-party listings conflict and are not the official creator rate: Yazing reports up to 8% of sales, Refermate reports up to 3.36%, and Sovrn states CSB commission rates ''could not be independently verified'' — so no single published creator rate was verified and commission_rate is left null.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://help.shopcsb.com/en-US/how-can-i-collaborate-with-csb-1872090', 'official_site', 'general', 'Creator saturation is NOT low: the official help page says ''Due to the high volume of applications, we''re unable to respond to each submission individually'' — supporting creator_saturation ''medium'', not ''low''. No fetched source states a commission cap or ''no cap/unlimited'' for the affiliate program, so commission_cap is ''unknown''.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 5, 14, 9, 5, '{"compensation": "Official terms publish no percentage and no cap wording; third-party rates conflict (3.36%-8%), so rate left null.", "contact_access": "Public creator application form on brand''s own site plus a published affiliates email in its official terms.", "credibility": "Established Australian brand founded by Rachel Dillon, ABN and NSW governing law stated in official terms.", "niche_fit": "Direct fitness/activewear fit for fitness UGC creators.", "opportunity_availability": "Publicly open partnerships application covering Creator Affiliate Program, UGC, gifting and paid partnership.", "ugc_evidence": "Official help page explicitly names UGC, affiliate partnerships, influencer gifting and brand collaborations."}'::jsonb);
