  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://whopaysinfluencers.com/brand/peppermayo/', 'listing', 'ugc_collab', 'Who Pays Influencers lists an open application for Peppermayo Brand Ambassador and Peppermayo PR List (campus), running on GRIN, with free product; it states ''Pay: Not published'' and ''No commission or pay terms published.''', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.Shopper.com/partnerships/peppermayo-com-affiliate-program', 'listing', 'compensation', 'Shopper.com listing claims a 5-10% payout, but this conflicts with Who Pays Influencers and NetInfluencer reporting the rate as not published/unknown, so no verified rate is recorded. COMMISSION_CAP: No ''no cap'', ''unlimited'' or other cap wording was found in any fetched official or listing source, so commission_cap is ''unknown''.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/peppermayo', 'listing', 'ugc_collab', 'CREATOR_SATURATION: Beacons Universe reports 1,388 creators have posted about Peppermayo all time, 70 creators mentioned it in the 30 days to 2026-11-20, and 67 sponsored posts mentioned it in the last 12 months — more than a low-saturation roster, supporting ''medium'' rather than ''low''.', 'publicly_reported', now());
