  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Quince Affiliate Program via LinkApprove — free to join, no separate Quince application', 'https://linkapprove.com/affiliate-programs/quince-affiliate-program', 'https://linkapprove.com/affiliate-programs/quince-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/quince-affiliate-program/', 'affiliate_network', 'compensation', 'FlexOffers programme listing: ''The payout is 2.4% of online sales from new customers. Restrictions apply.'' with a 30-day cookie duration. No cap / ''no cap'' / ''unlimited earnings'' wording is stated.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/quince-affiliate-program', 'affiliate_network', 'affiliate', 'LinkApprove listing corroborates 2.4% per sale, 30-day cookie, new US customers only, free to join with no separate Quince application and decision usually within 2 business days. It also notes EPC is not published because ''our sample on this program is too small to mean anything''.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabfeed.io/brands/quince', 'listing', 'ugc_collab', 'Creator saturation for PAID partnerships is low: CollabFeed tracks only ''15 tracked creator partnerships'' with ''14 unique creators'' across Instagram, TikTok and YouTube for Quince (14 YouTube posts, 1 TikTok post), a small paid-creator footprint for a brand of this scale. This supports creator_saturation ''low'' for paid partnerships; no fetched source states an uncapped commission, so commission_cap is ''unknown''.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://qa.onequince.com/partner-offers/ecobee?tracker=landingPage', 'official_site', 'contact', 'Official Quince partner-offers pages state: ''We''re always looking for more like-minded partners to join our program. Please reach out to brandpartnerships@onequince.com to connect.''', 'verified', now());
