  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.netinfluencer.com/white-fox-influencer-program/', 'creator_report', 'ugc_collab', 'Creator saturation is HIGH, not low: the guide lists numerous macro-influencer ambassadors across TikTok, Instagram and YouTube, ambassador content under #whitefoxoasis, notes the brand was built with influencer marketing and ''doesn''t really sponsor micro-influencers... they stick to macro-influencers and content creators with larger audiences.'' No fetched source states an uncapped commission, so commission_cap is ''unknown''.', 'publicly_reported', now());
