  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.motelrocks.com/pages/about-motel-rocks', 'official_site', 'general', 'Official About page: Motel was founded by Will and Andy on a 1990s road trip, began selling reworked vintage at London markets, and its London design studio works with a Bali production team; still independent.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://motelrocks.zendesk.com/hc/en-us/profiles/554240432-Motel-Rocks?filter_by=articles&page=2&sort_by=votes', 'official_site', 'contact', 'Official Motel Rocks Help Center ''Collaborations'' entry: ''If you would like to collab with Motel, or have any questions regarding being an influencer, please contact the team and email influencers@motelrocks.com'' — this email route is the only current creator route found; there is NO public affiliate/ambassador application form.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/motel-rocks-affiliate-program/', 'affiliate_network', 'affiliate', 'FlexOffers lists the Motel Rocks program as DEACTIVATED, with a historical payout of 9.6% on sales and a 60-day cookie, last updated 2026-03-31. Paid On Results likewise states ''This Affiliate Program has now closed.'' No current joinable affiliate program was verified. COMMISSION_CAP: No cap or ''no cap/unlimited'' wording was found in any fetched listing, so commission_cap is ''unknown''.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/motelrocks-com-affiliate-program', 'listing', 'compensation', 'Shopper.com listing claims 5-10% payout, but the underlying network programs are shown as deactivated/closed by FlexOffers and Paid On Results, so no current commission rate is recorded as verified.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.gigainfluence.com/research/brands-that-hire-small-fashion-creators-2026', 'listing', 'ugc_collab', 'CREATOR_SATURATION = LOW: GigaInfluence''s 2026 research on brands that hire small fashion creators groups Motel Rocks among the brands with smaller creator programs, reaching 1.26% of small fashion creators (100K-500K follower segment share data), indicating a comparatively small creator program.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabquill.com/best-brands/fashion', 'listing', 'ugc_collab', 'CollabQuill lists Motel Rocks under fashion brands for creators with ''Gifting'' and ''Paid partnerships'', noting it works with creators through gifting and paid partnerships and spreads through try-on/outfit content on TikTok.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 12, 4, 8, 3, 5, '{"compensation": "No current published commission: historical FlexOffers rate was 9.6% but that program is deactivated and Paid On Results is closed; no cap terms found.", "contact_access": "No application form; only a published influencer collaborations email on the official help center.", "credibility": "Established independent London brand founded in 1999, verified on its official site, with wholesale partners such as ASOS.", "niche_fit": "Strong Gen Z women''s Y2K/vintage fashion fit for UGC, slightly narrower aesthetic than the other brands in this batch.", "opportunity_availability": "No publicly open affiliate/ambassador application found; collabs are by email pitch only and legacy affiliate programs are closed.", "ugc_evidence": "Documented gifting and paid partnerships and a smaller creator program in GigaInfluence research, but no standing public creator program page."}'::jsonb);
