  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://share.sundaysfordogs.com/zone/terms?journey.campaign_id=7094265081383182478', 'official_site', 'affiliate', 'Brand''s own Ambassador Program terms: participants must live in the US and have content featuring their dog; perks include free product (1 month of Sundays), a partner link/code offering 50% off a first order, and ''Commission: 15% lifetime commission on sales and recurring subscription orders'', plus performance bonus milestones.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://share.sundaysfordogs.com/zone/terms?journey.campaign_id=7094265081383182478', 'official_site', 'compensation', 'Commission cap: UNKNOWN. The ambassador terms publish 15% lifetime commission with no earnings cap stated in the fetched terms, but no fetched source contains explicit ''no cap'' / ''unlimited earnings'' language or describes Sundays earnings as uncapped, so uncapped was not claimed per the evidence standard. ''Lifetime'' refers to recurring commission duration, not a verified earnings cap status.', 'needs_review', now());
