  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 16, 9, 8, 4, '{"compensation": "15% lifetime commission on sales and recurring subscription orders in the brand''s own terms is strong and recurring; cap status unverified, and a separate Impact route pays a flat $5.", "contact_access": "Network listings (Awin/Impact) plus a published affiliates email, but no creator application form on the main storefront was fetched \u2014 middle band.", "credibility": "Established US DTC brand, veterinarian-founded, with real storefront and active Awin and Impact programs.", "niche_fit": "Dog-only food brand; feeding-routine and transition content fits dog-parent creators well, though narrower than multi-pet tech/accessories.", "opportunity_availability": "Public ambassador terms and open Awin/Impact sign-up routes are available today; joining is via network/email rather than an own-site form.", "ugc_evidence": "Public Ambassador Program with creator content required is documented in its own terms, BravoDM and a UGC brand hit list, but no named creator example was fetched."}'::jsonb);
