  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ettitude.com.au/pages/affiliate', 'official_site', 'affiliate', 'Official Ettitude affiliate page (AU site for the same brand): base offer 9% on sales, 45-day cookie, 30-day lookback, $200 high AOV, commission on all products referred customers purchase, monthly payments, via Rakuten LinkShare network. Program described as free, simple and secure.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ettitude.com.au/pages/affiliate', 'official_site', 'compensation', 'Commission-cap status: official page states 9% base on sales and ''receive commission on all products'' plus ''endless rewards'' phrasing, with no maximum earnings cap mentioned, and InfluencerRate states ''the more you promote, the more you earn'' - but no explicit ''no cap''/''unlimited'' term was found on fetched pages. Per strict rule, commission_cap is set to unknown, not uncapped.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ettitude.com.au/pages/affiliate', 'official_site', 'ugc_collab', 'Creator saturation low evidence: affiliate route has low creator-program visibility - no dedicated US .com creator portal was found in search, the join route is a single AU affiliate page via Rakuten LinkShare plus a FAQ contact through third-party DMI Partners (ettitude@dmipartners.com), and the brand is actively inviting joins on that page (''Join The Ettitude Affiliate Program''). Few published creator-program listings were found beyond Lasso and InfluencerRate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/ettitude-holdings-inc/', 'listing', 'affiliate', 'Lasso listing for Ettitude Holdings Inc: Home category, up to 15.0% commission, 14-day cookie, $10 payout threshold, described for bloggers/influencers passionate about sustainable living and home decor. Official AU page base rate of 9% is used as the commission_rate in this record.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://faq.ettitude.com.au/en-US/do-you-have-an-affiliate-program-22977', 'official_site', 'general', 'Official FAQ confirms Ettitude offers an affiliate program for individuals sharing passion for sustainability/eco-conscious living, earning commission on bedding and lifestyle products, with dedicated team contact ettitude@dmipartners.com.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 13, 9, 8, 5, '{"compensation": "Published 9% base on official page (up to 15% on Lasso listing), $200 AOV and 45-day cookie; cap status unknown so not scored as uncapped.", "contact_access": "Join route is network-based via Rakuten LinkShare from the AU affiliate page plus a published DMI contact email - middle band, not a US own-site creator portal.", "credibility": "Established B Corp sustainable bedding brand with real storefront and 130K-follower Instagram presence reported in fetched posts.", "niche_fit": "Bamboo bedding, sheets and sleepwear fit home, sustainability and sleep creator niches well.", "opportunity_availability": "Open public join invitation on official affiliate page via Rakuten signup.", "ugc_evidence": "Affiliate program explicitly for bloggers/creators and UGC-style product reviews visible on official Instagram, but no named UGC/ambassador program on own site."}'::jsonb);
